package com.example.madfinalproject;
import android.content.Intent; import android.os.Bundle; import android.widget.TextView; import androidx.appcompat.app.AppCompatActivity;
public class PteReportsActivity extends AppCompatActivity {protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_ielts_reports);PteUiAdapter.apply(findViewById(android.R.id.content));((TextView)findViewById(R.id.tabReports)).setTextColor(PteUiAdapter.TEAL);wire();}private void wire(){findViewById(R.id.btnBack).setOnClickListener(v->finish());findViewById(R.id.tabOverview).setOnClickListener(v->open(PtePreparationActivity.class));findViewById(R.id.tabLessons).setOnClickListener(v->open(PteLessonsActivity.class));findViewById(R.id.tabPractice).setOnClickListener(v->open(PtePracticeActivity.class));findViewById(R.id.tabMockTests).setOnClickListener(v->open(PteMockTestsActivity.class));}private void open(Class<?> c){startActivity(new Intent(this,c));finish();}}
